<script lang="ts">
 import {onMount} from 'svelte';import {invoke} from '@tauri-apps/api/core';import {listen} from '@tauri-apps/api/event';import {save} from '@tauri-apps/plugin-dialog';import {t,type MessageKey} from './i18n';import {preferences,session} from './preferences.svelte';import type {FileInfo} from './columns';
 let {file}:{file:FileInfo}=$props();type Column={root:number;name:string;candidate:boolean};let columns=$state<Column[]>([]),selected=$state<number[]>([]),manual=$state<number[]>([]),include=$state(true),existing=$state(false),n=$state(preferences.sample_n),cap=$state(preferences.cap),mode=$state('head'),busy=$state(false),status=$state(''),error=$state(''),request='',disposed=false;
 let report=$state<{rows:number;columns:number;truncated:number;cleaned:number;warnings:string[]}|null>(null);
 async function run(){if(busy||session.task)return;busy=true;report=null;error='';request=crypto.randomUUID();try{const outPath=await save({defaultPath:file.name.replace(/\.parquet$/i,'')+'.dictionary.xlsx',filters:[{name:'Excel',extensions:['xlsx']}]});if(!outPath||disposed)return;status=t('dictionaryWorking');report=await invoke('export_dictionary',{id:file.id,options:{include_sample:include,sample:{mode,n,columns:selected},cap,existing_only:existing,manual_columns:manual},outPath,request});status=t('exportDone');}catch(e){const v=e as {code?:string;detail?:string};error=t((['cancelled','task_busy','file_changed','export_failed','parse_failed','invalid_request','resource_limit'].includes(v.code??'')?v.code:'unknown') as MessageKey)+(v.detail?' '+v.detail:'');}finally{busy=false;}}
 onMount(()=>{let off:(()=>void)|undefined;void(async()=>{try{const cleanup=await listen<{request:string;done:number;phase:string}>('dictionary_progress',e=>{if(e.payload.request===request&&!disposed)status=`${t(('dictionaryPhase_'+e.payload.phase) as MessageKey)} · ${e.payload.done}`;});if(disposed){cleanup();return;}off=cleanup;columns=await invoke('enum_catalog',{id:file.id});selected=columns.map(c=>c.root);}catch(e){error=String(e);}})();return()=>{disposed=true;off?.();};});
</script>
<section class="dictionary-panel"><h2>{t('dictionary')}</h2><p>{t('dictionaryHint')}</p>
 <label><input type="checkbox" bind:checked={existing} disabled={busy}/>{t('existingEnumsOnly')}</label><label>cap <input aria-label={t('dictionaryCap')} type="number" min="50" max="5000" bind:value={cap} disabled={busy||existing}/></label>
 {#if !existing}<details><summary>{t('manualEnumColumns')}</summary>{#each columns.filter(c=>!c.candidate) as c}<label><input type="checkbox" bind:group={manual} value={c.root} disabled={busy}/>{c.name}</label>{/each}</details>{/if}
 <label><input type="checkbox" bind:checked={include} disabled={busy}/>{t('includeSample')}</label>
 {#if include}<div class="sample-options"><label>{t('sampleMode')}<select bind:value={mode} disabled={busy}><option value="head">{t('headRows')}</option><option value="uniform">{t('uniformRows')}</option></select></label><label>{t('sampleCount')}<input aria-label={t('dictionaryN')} type="number" min="1" max="1000000" bind:value={n} disabled={busy}/></label><details><summary>{t('chooseColumns')} ({selected.length}/{columns.length})</summary>{#each columns as c}<label><input type="checkbox" bind:group={selected} value={c.root} disabled={busy}/>{c.name}</label>{/each}</details></div>{/if}
 <p class="dictionary-scope">{t(existing?'existingEnumsOnly':'dictionaryAllCandidates')} · cap {cap} · {include?`${t('sampleRows')}: ${n} / ${t('columns')}: ${selected.length} / ${t(mode==='head'?'headRows':'uniformRows')}`:t('noSample')} · {preferences.time_mode==='utc'?'UTC':t('localTime')}</p>
 <button disabled={busy||!!session.task||!columns.length||!Number.isInteger(cap)||cap<50||cap>5000||(include&&(!selected.length||!Number.isInteger(n)||n<1||n>1000000))} onclick={run}>{t('exportDictionary')}</button>
 {#if busy}<button onclick={()=>invoke('cancel_task',{id:file.id,request})}>{t('cancelTask')}</button>{/if}
 {#if status}<p role="status">{status}</p>{/if}{#if error}<p role="alert">{error}</p>{/if}{#if report}<p class="dictionary-report">{t('exportDone')} · {t('truncatedCells')}: {report.truncated} · {t('cleanedCells')}: {report.cleaned}</p>{#each report.warnings as warning}<p>{t('cacheWarning')} {warning}</p>{/each}{/if}
</section>
<style>.dictionary-panel{padding:22px;border:1px solid var(--line);background:var(--surface);border-radius:9px;margin:16px 0}h2{font-size:18px}p{font-size:12px;color:var(--muted);line-height:1.7}label{display:flex;align-items:center;gap:8px;margin:12px 0;font-size:13px}input,select,button{font:inherit;color:var(--text);background:var(--bg);border:1px solid var(--line);border-radius:5px;padding:8px}input[type=number]{width:130px}button{margin-right:10px}.sample-options{padding:0 16px;border-left:2px solid var(--line)}details{max-height:220px;overflow:auto;font-size:12px}.dictionary-scope{padding:12px;background:var(--soft)}</style>
